def collapse_ints(nums: list[int]) -> str:
    """Sort distinct ints; write runs of 4+ consecutive as first-last.

    A negative range endpoint is wrapped in parentheses; standalone
    numbers are written plainly. Empty input yields an empty string.
    """
    values = sorted(set(nums))
    if not values:
        return ""

    def endpoint(value: int) -> str:
        """Format a range endpoint, parenthesizing negatives."""
        return f"({value})" if value < 0 else str(value)

    parts: list[str] = []
    i = 0
    n = len(values)
    while i < n:
        j = i
        while j + 1 < n and values[j + 1] == values[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            parts.append(endpoint(values[i]) + "-" + endpoint(values[j]))
        else:
            parts.extend(str(v) for v in values[i:j + 1])
        i = j + 1
    return ",".join(parts)

